// === Tab: sketch ===
// https://openprocessing.org/sketch/2273587

let lines
let g
let lastTime = 0
let bg
let gSize // graphics size
let rSize // rendered size

let palette = [
	'#874286',
	'#856596',
	'#fc814a',
	'#f9c8ce',
	'#a8d7a8',
	'#b6cccc',
	'#8aadbc',
	'#7a7eb8',
]

function setSizesAndBg() {
	bg = chroma(random(palette)).brighten(1).hex()
	rSize = floor(max(width, height) * 0.8)
	gSize = floor(rSize * 0.7)
}

function setup() {
	createCanvas(windowWidth, windowHeight)
	setSizesAndBg()
	g = createGraphics(gSize, gSize)
	let pd = Math.min(pixelDensity(), 2)

	lines = new Lines(g, pd, palette)
	window.lines = lines
}

function draw() {
	let ms = millis()
	let delta = ms - lastTime
	lastTime = ms

	let done = lines.update(delta)
	// clear()
	background(bg)
	translate((width - rSize) / 2, (height - rSize) / 2)

	noStroke()
	fill(255)
	rect(0, 0, rSize, rSize)
	image(g, 0, 0, rSize, rSize)

	stroke(bg)
	strokeWeight(10)
	noFill()
	rect(0, 0, rSize, rSize)
}

function windowResized() {
	resizeCanvas(window.innerWidth, window.innerHeight)
	sz = floor(max(width, height) * 0.7)
}

function mousePressed() {
	lines.reset()
	setSizesAndBg()
	g.resizeCanvas(gSize, gSize)
	lines = new Lines(g, min(pixelDensity(), 2), palette)
}

// === Tab: lines ===
function distSq(p1, p2) {
	return Math.pow(p1[0] - p2[0], 2) + Math.pow(p1[1] - p2[1], 2)
}

class Lines {
	constructor(g, pixelDensity, palette) {
		this.g = g
		this.width = g.width
		this.height = g.height
		this.pixelDensity = pixelDensity
		this.longLineMinSq = Math.pow(this.width * 0.1, 2)
		this.g.pixelDensity(pixelDensity)
		this.g.loadPixels()
		this.palette = palette

		this.stepRate = 5000
		this.wiggliness = 0.1
		this.imprecision = 1
		this.minLineLengthStart = 15
		this.minLineLengthEnd = 7
		this.minLineLength = 15
		this.maxLineLength = 500
		this.stepMult = 1
		this.alphaThreshold = 20
		this.colorMove = 0.00009
		this.stopAtFails = 1000
		this.lineWidth = 3

		this.currentLine = []
		this.linesDrawn = 0
		this.lastPoint = null
		this.longLines = []
		this.angle = Math.random() * Math.PI * 2
		this.lineAngle = this.angle
		this.done = false
		this.colorIndex = 0
		this.failsCount = 0
		this.lineLookPoint = [floor(random(width * 0.25, width * 0.75)), floor(random(height * 0.25, height * 0.75))]
	}

	getPxIndex(x, y) {
		return (y * this.width * this.pixelDensity + x) * 4 * this.pixelDensity
	}

	getBlankPixelNear(cx, cy, radius) {
		let tries = 0
		let rangeX = [cx - radius, cx + radius]
		let rangeY = [cy - radius, cy + radius]
		if (rangeX[0] < 0) rangeX[0] = 0
		if (rangeX[1] >= this.width) rangeX[1] = this.width - 1
		if (rangeY[0] < 0) rangeY[0] = 0
		if (rangeY[1] >= this.height) rangeY[1] = this.height - 1

		while (tries < 10) {
			let [x, y] = [floor(random(rangeX[0], rangeX[1])), floor(random(rangeY[0], rangeY[1]))]
			if (this.isBlankIshPx(x, y)) {
				return [x, y]
			}
			tries++
		}

		return false
	}

	isBlankIshPx(x, y) {
		let ind = this.getPxIndex(x, y)
		return this.g.pixels[ind + 3] < this.alphaThreshold
	}

	getLinePoints(x, y) {
		let curX = x
		let curY = y
		let points = []
		var tries = 0
		while (points.length < this.maxLineLength && tries < 10) {
			let nextX = curX + Math.cos(this.lineAngle) * this.stepMult
			let nextY = curY + Math.sin(this.lineAngle) * this.stepMult

			if (nextX < 0 || nextX >= this.width || nextY < 0 || nextY >= this.height) {
				break
			} else if (!this.isBlankIshPx(Math.round(nextX), Math.round(nextY))) {
				this.lineAngle += random(this.wiggliness) * random([-1, 1])
				tries++
			} else {
				points.push([curX, curY])
				curX = nextX
				curY = nextY
				let angleDiff = this.lineAngle - this.angle
				if (Math.abs(angleDiff) > Math.PI * 0.1) {
					if (angleDiff > 0) {
						this.lineAngle -= Math.PI * 0.1
					} else {
						this.lineAngle += Math.PI * 0.1
					}
				} else {
					this.lineAngle += random(-this.wiggliness / 2, this.wiggliness / 2)
				}
				this.lineAngle += random(-this.wiggliness / 2, this.wiggliness / 2)
				tries = 0
			}
		}

		if (points.length < this.minLineLength) {
			return false
		}

		return points
	}

	addFail() {
		this.failsCount++
		if (this.failsCount > 10 && this.longLines.length) {
			let longLine = this.longLines.shift()
			this.lineLookPoint = longLine[Math.floor(longLine.length / 2)]
		} else if (this.failsCount > 50) {
			this.lineLookPoint = [Math.floor(random(this.width)), Math.floor(random(this.height))]
		}
		if (this.failsCount > 500) {
			this.minLineLength = max(this.minLineLength - 5, this.minLineLengthEnd)
		}
		if (this.failsCount > this.stopAtFails) {
			this.done = true
		}
	}

	getLine() {
		let pixel = this.getBlankPixelNear(this.lineLookPoint[0], this.lineLookPoint[1], 100)
		if (!pixel) return false

		let [x1, y1] = pixel
		var points = this.getLinePoints(x1, y1)

		if (!points) return false

		if (distSq(points[0], points[points.length - 1]) > this.longLineMinSq) {
			this.longLines.push(points)
		}

		this.currentLine = points
		return true
	}

	finishLine() {
		this.lastPoint = null
		this.g.loadPixels()
		this.currentLine = []
		if (this.linesDrawn % 100 === 0) {
			this.angle = this.angle + Math.random() * this.wiggliness - this.wiggliness / 2
		}
		this.lineAngle = this.angle
	}

	lineStep() {
		if (this.currentLine.length < 2) return

		let [x1, y1] = this.lastPoint ?? this.currentLine[0]

		this.colorIndex += this.colorMove
		if (this.colorIndex >= this.palette.length) {
			this.colorIndex = 0
		}
		let c1 = this.palette[Math.floor(this.colorIndex)]
		let c2 = this.palette[Math.ceil(this.colorIndex)]
		if (!c2) c2 = this.palette[0]
		let color = chroma.mix(c1, c2, this.colorIndex % 1, 'hsl').hex()
		this.g.stroke(color)
		this.g.strokeWeight(this.lineWidth)

		let [x2, y2] = this.currentLine[1]
		let n = this.g.noise(x2 * 0.1, y2 * 0.1) * this.imprecision - this.imprecision / 2
		x2 += n
		y2 += n
		this.g.line(x1, y1, x2, y2)
		this.lastPoint = [x2, y2]
		this.currentLine.shift()
		if (this.currentLine.length < 2) {
			this.finishLine()
		}
	}

	step() {
		if (this.done) return
		if (this.currentLine.length >= 2) {
			this.g.push()
			this.lineStep()
			this.g.pop()
		} else {
			if (!this.getLine()) {
				this.addFail()
			} else {
				this.failsCount = 0
			}
		}
	}

	update(delta) {
		let steps = Math.round((delta / 1000) * this.stepRate)
		while (steps > 0) {
			this.step()
			steps--
		}

		return this.done
	}

	reset() {
		this.g.clear()
		this.g.loadPixels()
		this.linesDrawn = 0
		this.done = false
		this.currentLine = []
		this.longLines = []
		this.failsCount = 0
		this.angle = Math.random() * Math.PI * 2
		this.minLineLength = this.minLineLengthStart
	}
}

